-- Reviewer feedback: GTM Plan, Launch Checklist, Status Report, Campaign Brief (Rhodes).

update templates
set
  name = 'GTM Plan',
  description = 'ICP, positioning, channels, enablement, and success metrics for a market launch',
  structure_json = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Business Goal"}]},{"type":"paragraph","content":[{"type":"text","text":"What business outcome this GTM motion must deliver (pipeline, adoption, revenue). Set Market and Audience in Properties → Targeting. Set GTM tier for how loud this launch should be.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Primary business goal and time horizon.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"ICP & Beachhead"}]},{"type":"paragraph","content":[{"type":"text","text":"Ideal customer profile and the first segment you will win — industry, size, trigger events. Avoid ''everyone''.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ICP: [firmographics / role / pains]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Beachhead: [narrow first market]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Exclusions: [who this is not for]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Positioning & Messaging"}]},{"type":"paragraph","content":[{"type":"text","text":"Value proposition vs status quo, and the single core message. Also clarify monetization: which plan/tier gets access, and is it included or paid?","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Positioning statement.]"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Message pillar 1]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Message pillar 2]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Proof point / case study]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pricing / packaging: [included in … / add-on / usage-based]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Channel Strategy"}]},{"type":"paragraph","content":[{"type":"text","text":"Operative matrix — no vague ''we''ll do social''. Channel | Tactic | Budget | Owner | Success metric.","marks":[{"type":"italic"}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Channel"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Tactic"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Budget"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Owner"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Success metric"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Channel]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Tactic]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Amount]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Owner]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Metric]"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Launch Sequencing"}]},{"type":"paragraph","content":[{"type":"text","text":"Pre-launch → launch → post-launch. target_launch_date in Properties is the GTM push date — it may differ from code deploy.","marks":[{"type":"italic"}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Phase"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Milestone"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Owner"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Target date"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Pre-launch"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Milestone]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Owner]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Date]"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Launch"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Milestone]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Owner]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Date]"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Post-launch"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[30/60/90 review]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Owner]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Date]"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Internal Enablement"}]},{"type":"paragraph","content":[{"type":"text","text":"Customers must not hear about the launch before Sales and Support. Training dates, FAQ location, battle cards, and demo scripts.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sales enablement: [when / assets]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Support FAQ / macros: [link]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CS / AM briefing: [when]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Internal announce: [when / channel]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Success Metrics & Decision Rules"}]},{"type":"paragraph","content":[{"type":"text","text":"Leading and lagging KPIs, plus what you do if the motion underperforms at day 30/60/90.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Primary KPI: [metric + target]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Guardrails: [CAC, win rate, cycle time]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If off-track: [decision rule]"}]}]}]}]}'::jsonb,
  metadata = '{"document_type":"gtm_plan","category":"marketing","use_cases":["Product launches","Campaign planning","Market entry"],"supported_views":["wiki","kanban","gantt","dashboard"],"schema_fields":[{"field_key":"status","field_label":"Status","field_type":"select","options":["draft","in_progress","done"],"ai_fill_enabled":true},{"field_key":"due_date","field_label":"Due","field_type":"date","ai_fill_enabled":true},{"field_key":"owner","field_label":"Owner","field_type":"text","ai_fill_enabled":true},{"field_key":"summary","field_label":"Summary","field_type":"textarea","ai_fill_enabled":true},{"field_key":"origin","field_label":"Origin","field_type":"relation","ai_fill_enabled":false},{"field_key":"gtm_status","field_label":"GTM status","field_type":"status","options":[{"value":"draft","label":"Draft","category":"unstarted"},{"value":"approved","label":"Approved","category":"unstarted"},{"value":"executing","label":"Executing","category":"started"},{"value":"complete","label":"Complete","category":"completed"}],"ai_fill_enabled":true},{"field_key":"target_launch_date","field_label":"Target launch date","field_type":"date","ai_fill_enabled":true},{"field_key":"gtm_tier","field_label":"GTM tier","field_type":"select","options":["tier_1","tier_2","tier_3"],"ai_fill_enabled":true},{"field_key":"primary_kpi","field_label":"Primary KPI","field_type":"text","ai_fill_enabled":true},{"field_key":"sponsor","field_label":"Sponsor","field_type":"text","ai_fill_enabled":true}],"schema_groups":[{"group_key":"targeting","group_label":"Targeting","repeatable":false,"fields":[{"sub_key":"market","field_label":"Market","field_type":"text","ai_fill_enabled":true},{"sub_key":"audience","field_label":"Audience","field_type":"text","ai_fill_enabled":true}]}],"default_properties":{"status":"draft","gtm_status":"draft","gtm_tier":"tier_2"}}'::jsonb
where slug = 'gtm-plan'
  and coalesce(is_system, false) = true
  and workspace_id is null;

update templates
set
  name = 'Launch Checklist',
  description = 'Cross-functional readiness, go/no-go criteria, rollback, and post-launch review',
  structure_json = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Launch Scope"}]},{"type":"paragraph","content":[{"type":"text","text":"What is shipping, to whom, and at what tier. Set Product and Market in Properties → Targeting. Paste the war-room link (Slack / Teams / open video call) here so the incident team knows where to gather.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Scope, audience, and launch tier.]"}]},{"type":"paragraph","content":[{"type":"text","text":"[War room / launch channel link:]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Readiness Checklist"}]},{"type":"paragraph","content":[{"type":"text","text":"Use the table: Area | Task | DRI | Status | Evidence. Every gate needs a named owner. ''In progress'' is not ready at T-72h.","marks":[{"type":"italic"}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Area"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Task"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"DRI"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Status"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Evidence"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Product / QA"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Gate]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Owner]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Not started]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Link]"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Engineering"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Monitoring / rollback]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Owner]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Not started]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Link]"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Marketing / GTM"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Assets / pages]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Owner]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Not started]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Link]"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Sales / CS"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Enablement / macros]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Owner]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Not started]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Link]"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Legal / Privacy"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Review]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Owner]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Not started]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Link]"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Analytics"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Events / dashboards]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Owner]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Not started]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Link]"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Go / No-Go Criteria"}]},{"type":"paragraph","content":[{"type":"text","text":"Conditions that must be true to launch. Named authority decides go, delay, or reduced scope — not sunk-cost momentum.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Criterion — must be true]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Go/no-go meeting: [date, T-72h]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Decision authority: [role/name]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Launch Day Plan"}]},{"type":"paragraph","content":[{"type":"text","text":"Comms timing, war-room coverage, feature flags / rollout phases. Keep the war-room link at the top of this doc.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Internal announce: [when / channel]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"External announce: [when / channel]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On-call / war room: [who + link]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Rollout phases: [%, criteria to expand]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Rollback Plan"}]},{"type":"paragraph","content":[{"type":"text","text":"Trigger, owner who can execute, and customer-facing recovery steps — write this before you need it.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Rollback trigger, owner, and steps.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Post-Launch Review"}]},{"type":"paragraph","content":[{"type":"text","text":"Retro within 72h and T+30 review against success criteria.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Retro owner / date: […]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Success criteria vs actuals: […]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Follow-ups: […]"}]}]}]}]}'::jsonb,
  metadata = '{"document_type":"launch_checklist","category":"marketing","use_cases":["Product launches","Feature rollouts","Release management"],"supported_views":["kanban","wiki"],"schema_fields":[{"field_key":"status","field_label":"Status","field_type":"select","options":["draft","in_progress","done"],"ai_fill_enabled":true},{"field_key":"due_date","field_label":"Due","field_type":"date","ai_fill_enabled":true},{"field_key":"owner","field_label":"Owner","field_type":"text","ai_fill_enabled":true},{"field_key":"summary","field_label":"Summary","field_type":"textarea","ai_fill_enabled":true},{"field_key":"origin","field_label":"Origin","field_type":"relation","ai_fill_enabled":false},{"field_key":"launch_date","field_label":"Launch date","field_type":"date","ai_fill_enabled":true},{"field_key":"launch_status","field_label":"Launch status","field_type":"status","options":[{"value":"planning","label":"Planning","category":"unstarted"},{"value":"ready","label":"Ready","category":"started"},{"value":"launched","label":"Launched","category":"completed"},{"value":"rolled_back","label":"Rolled back","category":"canceled"}],"ai_fill_enabled":true},{"field_key":"launch_tier","field_label":"Launch tier","field_type":"select","options":["soft","ga","major"],"ai_fill_enabled":true},{"field_key":"go_nogo_date","field_label":"Go/no-go meeting","field_type":"date","ai_fill_enabled":false}],"schema_groups":[{"group_key":"targeting","group_label":"Targeting","repeatable":false,"fields":[{"sub_key":"product","field_label":"Product","field_type":"text","ai_fill_enabled":true},{"sub_key":"market","field_label":"Market","field_type":"text","ai_fill_enabled":true}]}],"default_properties":{"status":"draft","launch_status":"planning"}}'::jsonb
where slug = 'launch-checklist'
  and coalesce(is_system, false) = true
  and workspace_id is null;

update templates
set
  name = 'Status Report',
  description = 'Async status for stakeholders — metrics, wins, blockers, and next steps (TL;DR lives in Properties → Summary)',
  structure_json = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Key Metrics"}]},{"type":"paragraph","content":[{"type":"text","text":"Put the TL;DR in Properties → Summary (don''t duplicate it here). Below: the numbers that matter this period, with trend.","marks":[{"type":"italic"}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Metric"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"This Period"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Trend"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Metric]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Value]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[↑/↓/→]"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Wins"}]},{"type":"paragraph","content":[{"type":"text","text":"What went well since the last report — outcomes, not activity lists.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Win]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Risks & Blockers"}]},{"type":"paragraph","content":[{"type":"text","text":"Make blockers actionable: tag the person who can unblock you (@Name) and what you need from them.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Risk] — @Name — [ask / decision needed]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Next Steps"}]},{"type":"paragraph","content":[{"type":"text","text":"What happens between now and the next report.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Next step]"}]}]}]}]}'::jsonb,
  metadata = '{"document_type":"weekly_status","category":"essentials","use_cases":["Status updates","Stakeholder reporting","Project health checks"],"supported_views":["dashboard","calendar","wiki"],"schema_fields":[{"field_key":"status","field_label":"Status","field_type":"select","options":["draft","in_progress","done"],"ai_fill_enabled":true},{"field_key":"due_date","field_label":"Due","field_type":"date","ai_fill_enabled":true},{"field_key":"owner","field_label":"Owner","field_type":"text","ai_fill_enabled":true},{"field_key":"summary","field_label":"Summary","field_type":"textarea","ai_fill_enabled":true},{"field_key":"origin","field_label":"Origin","field_type":"relation","ai_fill_enabled":false},{"field_key":"period_end","field_label":"Period ending","field_type":"date","ai_fill_enabled":true},{"field_key":"report_period","field_label":"Period label","field_type":"text","ai_fill_enabled":true},{"field_key":"health","field_label":"Health","field_type":"status","options":[{"value":"on_track","label":"On track","category":"started"},{"value":"at_risk","label":"At risk","category":"started"},{"value":"off_track","label":"Off track","category":"started"}],"ai_fill_enabled":true}],"default_properties":{"status":"draft","health":"on_track"}}'::jsonb
where slug = 'weekly-status'
  and coalesce(is_system, false) = true
  and workspace_id is null;

update templates
set
  name = 'Campaign Brief',
  description = 'Objective, single key message, channels, budget, assets, and success metrics',
  structure_json = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Objective"}]},{"type":"paragraph","content":[{"type":"text","text":"One campaign goal tied to a business outcome. Set Channel / Market / Audience in Properties → Targeting (same segments as experiments when possible).","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Campaign objective.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Audience & Insight"}]},{"type":"paragraph","content":[{"type":"text","text":"Who this is for, and the insight that makes the message land. Prefer the same Audience value as in Properties → Targeting.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Audience + insight.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Key Message"}]},{"type":"paragraph","content":[{"type":"text","text":"One striking message — not three benefits at once. Define the exact Call-to-Action (CTA) the user should take.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Key message.]"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Proof point 1]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Proof point 2]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CTA: [exact button / link action]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Channels & Tactics"}]},{"type":"paragraph","content":[{"type":"text","text":"Channel mix with tactic, owner, and timing. Keep primary Channel in Properties.","marks":[{"type":"italic"}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Channel"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Tactic"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Owner"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Timing"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Channel]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Tactic]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Owner]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Dates]"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Creative & Assets"}]},{"type":"paragraph","content":[{"type":"text","text":"Deliverables for design/copy — formats, quantities, landing pages. Link Figma or Drive folders here so handoff is one click.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Asset — format / owner / due / link]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Budget & Timeline"}]},{"type":"paragraph","content":[{"type":"text","text":"Total budget split and campaign window. Enter Budget in Properties as a number in your workspace currency (keep currency consistent across campaigns).","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Window: [start → end]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Paid / creative / tools / contingency: [split]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Success Metrics & Reporting"}]},{"type":"paragraph","content":[{"type":"text","text":"One primary metric, a few secondary, and reporting cadence.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Primary: [metric + target + baseline]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Secondary: [metric]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reporting: [daily / weekly / final]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Approvals"}]},{"type":"paragraph","content":[{"type":"text","text":"Who must sign off before launch, and by when.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Stakeholder] — [what they approve] — Due: [date]"}]}]}]}]}'::jsonb,
  metadata = '{"document_type":"campaign_brief","category":"marketing","use_cases":["Marketing campaigns","Product launches","Brand initiatives"],"supported_views":["wiki","kanban","gantt","dashboard"],"schema_fields":[{"field_key":"status","field_label":"Status","field_type":"select","options":["draft","in_progress","done"],"ai_fill_enabled":true},{"field_key":"due_date","field_label":"Due","field_type":"date","ai_fill_enabled":true},{"field_key":"owner","field_label":"Owner","field_type":"text","ai_fill_enabled":true},{"field_key":"summary","field_label":"Summary","field_type":"textarea","ai_fill_enabled":true},{"field_key":"origin","field_label":"Origin","field_type":"relation","ai_fill_enabled":false},{"field_key":"campaign_status","field_label":"Campaign status","field_type":"status","options":[{"value":"planning","label":"Planning","category":"unstarted"},{"value":"live","label":"Live","category":"started"},{"value":"complete","label":"Complete","category":"completed"}],"ai_fill_enabled":true},{"field_key":"channels","field_label":"Channel mix","field_type":"multi_select","options":["email","social","paid","organic","pr","events","partners"],"ai_fill_enabled":true},{"field_key":"budget","field_label":"Budget","field_type":"number","options":{"unit":"currency"},"ai_fill_enabled":false},{"field_key":"campaign_window","field_label":"Campaign window","field_type":"date_range","ai_fill_enabled":true},{"field_key":"primary_metric","field_label":"Primary metric","field_type":"text","ai_fill_enabled":true}],"schema_groups":[{"group_key":"targeting","group_label":"Targeting","repeatable":false,"fields":[{"sub_key":"channel","field_label":"Channel","field_type":"text","ai_fill_enabled":true},{"sub_key":"market","field_label":"Market","field_type":"text","ai_fill_enabled":true},{"sub_key":"audience","field_label":"Audience","field_type":"text","ai_fill_enabled":true}]}],"default_properties":{"status":"draft","campaign_status":"planning"}}'::jsonb
where slug = 'campaign-brief'
  and coalesce(is_system, false) = true
  and workspace_id is null;

insert into metadata_schemas (workspace_id, field_key, field_label, field_type, options, ai_fill_enabled)
select ms.workspace_id, v.field_key, v.field_label, v.field_type, v.options, v.ai_fill_enabled
from (
  select distinct workspace_id from metadata_schemas
  where field_key in ('gtm_status', 'health', 'campaign_status', 'launch_status')
) ms
cross join (
  values
    ('gtm_tier', 'GTM tier', 'select', '["tier_1","tier_2","tier_3"]'::jsonb, true),
    ('period_end', 'Period ending', 'date', null::jsonb, true)
) as v(field_key, field_label, field_type, options, ai_fill_enabled)
where not exists (
  select 1 from metadata_schemas e
  where e.workspace_id = ms.workspace_id and e.field_key = v.field_key
);

-- Clarify Status Report period label vs sortable period_end.
update metadata_schemas
set field_label = 'Period label'
where field_key = 'report_period'
  and field_label = 'Report period';
